//! Shell completion generation, installation, and multi-shell auto-suggestion support.
//!
//! Provides rich completions with parameter value candidates and descriptive tooltips
//! compatible with `zsh-autosuggestions`, `fzf-tab`, `fish`, `pwsh`, `powershell.exe`,
//! `elvish`, `nushell`, and `carapace` specifications.

use std::io;
use std::path::{Path, PathBuf};

use clap_complete::{generate, shells};

use crate::init::Shell;

/// Result of installing shell completions.
#[derive(Debug, Clone)]
pub struct CompletionInstallResult {
    pub shell: Shell,
    pub script_path: Option<PathBuf>,
    pub rc_path: Option<PathBuf>,
    pub script_written: bool,
    pub rc_updated: bool,
    pub message: String,
}

/// Generate completions and write to stdout (used by CLI or test suites).
pub fn generate_completions(shell: Shell, cmd: &mut clap::Command) -> io::Result<()> {
    let script = generate_completion_script(shell, cmd);
    print!("{script}");
    Ok(())
}

/// Install shell completions to the shell's standard configuration directory
/// and idempotently attach source lines to the shell profile / rc file.
pub fn install_completions(
    shell: Shell,
    cmd: &mut clap::Command,
) -> io::Result<CompletionInstallResult> {
    let script = generate_completion_script(shell, cmd);
    let script_path = shell.completions_script_path();
    let rc_path = shell.shell_rc_path();

    let mut script_written = false;
    let mut rc_updated = false;

    if let Some(ref sp) = script_path {
        script_written = forgum_platform::write_file_if_changed(sp, &script)?;
    }

    if let (Some(ref sp), Some(ref rc)) = (&script_path, &rc_path) {
        if let Some(source_cmd) = shell.shell_source_command(sp) {
            let begin_marker = forgum_platform::COMPLETIONS_MARKER_BEGIN;
            let end_marker = forgum_platform::COMPLETIONS_MARKER_END;
            let block = format!(
                "{begin_marker}\n# Generated by forgum completions — do not edit by hand\n{source_cmd}\n{end_marker}\n"
            );
            let current_rc = std::fs::read_to_string(rc).unwrap_or_default();
            let new_rc = forgum_platform::update_delimited_block(
                &current_rc,
                begin_marker,
                end_marker,
                &block,
            );
            rc_updated = forgum_platform::write_file_if_changed(rc, &new_rc)?;
        }
    }

    let message = format_install_message(
        shell,
        script_path.as_deref(),
        rc_path.as_deref(),
        script_written,
        rc_updated,
    );

    Ok(CompletionInstallResult {
        shell,
        script_path,
        rc_path,
        script_written,
        rc_updated,
        message,
    })
}

fn format_install_message(
    shell: Shell,
    script_path: Option<&Path>,
    rc_path: Option<&Path>,
    script_written: bool,
    rc_updated: bool,
) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "\x1b[1;32m✓\x1b[0m Forgum completions configured for \x1b[1m{}\x1b[0m\n",
        shell
    ));

    if let Some(sp) = script_path {
        let status = if script_written {
            "installed"
        } else {
            "up to date"
        };
        out.push_str(&format!(
            "  \x1b[36m•\x1b[0m Script ({}): {}\n",
            status,
            sp.display()
        ));
    }

    if let Some(rc) = rc_path {
        let status = if rc_updated {
            "updated"
        } else {
            "already configured"
        };
        out.push_str(&format!(
            "  \x1b[36m•\x1b[0m Profile ({}): {}\n",
            status,
            rc.display()
        ));
        out.push_str(&format!("\n\x1b[90mTo activate immediately in your current session:\x1b[0m\n  \x1b[1msource {}\x1b[0m\n", rc.display()));
    } else if shell == Shell::Carapace {
        out.push_str("  \x1b[36m•\x1b[0m Carapace spec registered. Completions will appear across all Carapace-managed shells.\n");
    }

    out
}

/// Generate completion script string for the target shell.
pub fn generate_completion_script(shell: Shell, cmd: &mut clap::Command) -> String {
    match shell {
        Shell::Bash => generate_bash_completions(cmd),
        Shell::Zsh => generate_zsh_completions(cmd),
        Shell::Fish => generate_fish_completions(),
        Shell::Pwsh | Shell::PowerShell => generate_powershell_completions(),
        Shell::Elvish => generate_elvish_completions(cmd),
        Shell::Nushell => generate_nushell_completions(),
        Shell::Carapace => generate_carapace_spec(),
        Shell::Xonsh => generate_xonsh_completions(),
        Shell::Tcsh => generate_tcsh_completions(),
        Shell::Ksh => generate_ksh_completions(cmd),
        Shell::Ion => generate_ion_completions(),
        Shell::Oil => generate_oil_completions(cmd),
        Shell::Yash => generate_yash_completions(),
        Shell::Cmd => {
            "rem forgum completions: cmd.exe does not support shell tab completion scripts\n"
                .to_string()
        }
    }
}

/// Freshness status of shell tab completions on the user's host system.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ShellCompletionStatus {
    /// Completion script is installed and matches the current version generator.
    UpToDate,
    /// Completion script is installed, but content differs from the current version generator.
    Outdated,
    /// Shell binary is installed and available on host, but completion script is not installed.
    AvailableNotInstalled,
    /// Shell binary is not available on this system.
    NotAvailable,
}

impl ShellCompletionStatus {
    pub fn badge(&self) -> &'static str {
        match self {
            Self::UpToDate => "\x1b[1;32m[Up to date]\x1b[0m",
            Self::Outdated => "\x1b[1;33m[OUTDATED - Update Available]\x1b[0m",
            Self::AvailableNotInstalled => "\x1b[1;36m[Available - Not Installed]\x1b[0m",
            Self::NotAvailable => "\x1b[90m[Shell Not Installed]\x1b[0m",
        }
    }
}

/// Inspection record for a specific shell's completion status.
#[derive(Debug, Clone)]
pub struct ShellCompletionInspection {
    pub shell: Shell,
    pub status: ShellCompletionStatus,
    pub script_path: Option<PathBuf>,
    pub rc_path: Option<PathBuf>,
}

/// Inspect the completion freshness status of a specific shell.
pub fn inspect_shell_completion(
    shell: Shell,
    cmd: &mut clap::Command,
) -> ShellCompletionInspection {
    let script_path = shell.completions_script_path();
    let rc_path = shell.shell_rc_path();
    let is_available = shell.is_available();

    let status = match &script_path {
        Some(path) if path.exists() => {
            let expected = generate_completion_script(shell, cmd);
            match std::fs::read_to_string(path) {
                Ok(existing)
                    if existing.replace("\r\n", "\n").trim()
                        == expected.replace("\r\n", "\n").trim() =>
                {
                    ShellCompletionStatus::UpToDate
                }
                _ => ShellCompletionStatus::Outdated,
            }
        }
        _ => {
            if is_available {
                ShellCompletionStatus::AvailableNotInstalled
            } else {
                ShellCompletionStatus::NotAvailable
            }
        }
    };

    ShellCompletionInspection {
        shell,
        status,
        script_path,
        rc_path,
    }
}

/// Inspect the completion freshness status across all supported shells.
pub fn inspect_all_shells_completion_status(
    cmd: &mut clap::Command,
) -> Vec<ShellCompletionInspection> {
    Shell::ALL
        .iter()
        .filter(|&&s| s != Shell::Cmd)
        .map(|&shell| inspect_shell_completion(shell, cmd))
        .collect()
}

/// Interactively prompt the user with a multi-choice menu to update shell completions
/// for available shells on the system.
pub fn interactive_update_completions(
    cmd: &mut clap::Command,
    force_interactive: bool,
) -> io::Result<()> {
    let inspections = inspect_all_shells_completion_status(cmd);
    let available_or_installed: Vec<_> = inspections
        .into_iter()
        .filter(|i| i.status != ShellCompletionStatus::NotAvailable)
        .collect();

    if available_or_installed.is_empty() {
        println!("\x1b[33mNo supported shells detected on this system.\x1b[0m");
        return Ok(());
    }

    let needs_update: Vec<_> = available_or_installed
        .iter()
        .filter(|i| {
            i.status == ShellCompletionStatus::Outdated
                || i.status == ShellCompletionStatus::AvailableNotInstalled
        })
        .collect();

    if needs_update.is_empty() {
        println!("\n\x1b[1;32m✓ All shell completions are up to date across your available shells:\x1b[0m");
        for inst in &available_or_installed {
            let path_str = inst
                .script_path
                .as_ref()
                .map(|p| p.display().to_string())
                .unwrap_or_else(|| "active".to_string());
            println!(
                "  \x1b[36m•\x1b[0m {:<12} \x1b[32m[Up to date]\x1b[0m \x1b[90m({})\x1b[0m",
                inst.shell, path_str
            );
        }
        println!();
        return Ok(());
    }

    let is_tty = forgum_platform::terminal::detect_capabilities().is_tty || force_interactive;

    println!("\n\x1b[1;35m━━━ Forgum Universal Shell Completions Manager ━━━\x1b[0m");
    println!("Detected shell environments and completion status on your system:\n");

    for (idx, item) in available_or_installed.iter().enumerate() {
        let num = idx + 1;
        let badge = item.status.badge();
        let target_path = item
            .script_path
            .as_ref()
            .map(|p| p.display().to_string())
            .unwrap_or_else(|| "standard path".into());
        println!(
            "  \x1b[1m[{num}]\x1b[0m {:<12} {:<32} \x1b[90m({})\x1b[0m",
            item.shell, badge, target_path
        );
    }

    if !is_tty {
        let outdated_existing: Vec<_> = available_or_installed
            .iter()
            .filter(|i| i.status == ShellCompletionStatus::Outdated)
            .collect();
        if !outdated_existing.is_empty() {
            println!(
                "\n\x1b[36m>> Non-interactive mode: Automatically updating {} outdated shell completion(s)...\x1b[0m",
                outdated_existing.len()
            );
            for item in outdated_existing {
                let res = install_completions(item.shell, cmd)?;
                print!("{}", res.message);
            }
        }
        return Ok(());
    }

    println!("\n\x1b[1;37mUpdate shell completions?\x1b[0m");
    println!("  \x1b[1;32m[A]\x1b[0m Update all available shells (Recommended)");
    println!(
        "  \x1b[1;36m[1..{}]\x1b[0m Select specific shells (comma-separated, e.g. 1, 2)",
        available_or_installed.len()
    );
    println!("  \x1b[1;31m[S]\x1b[0m Skip for now\n");
    print!("\x1b[1;33mSelect [A]: \x1b[0m");
    let _ = io::Write::flush(&mut io::stdout());

    let mut input = String::new();
    if io::stdin().read_line(&mut input).is_err() {
        return Ok(());
    }
    let choice = input.trim().to_lowercase();

    let selected_indices: Vec<usize> = if choice.is_empty()
        || choice == "a"
        || choice == "all"
        || choice == "y"
        || choice == "yes"
    {
        (0..available_or_installed.len()).collect()
    } else if choice == "s" || choice == "skip" || choice == "n" || choice == "no" || choice == "q"
    {
        println!(
            "\x1b[90mCompletions update skipped. You can run 'forgum completions' at any time.\x1b[0m\n"
        );
        return Ok(());
    } else {
        choice
            .split(&[',', ' ', ';'][..])
            .filter_map(|s| s.trim().parse::<usize>().ok())
            .filter(|&n| n >= 1 && n <= available_or_installed.len())
            .map(|n| n - 1)
            .collect()
    };

    if selected_indices.is_empty() {
        println!("\x1b[90mNo valid shells selected. Completions update skipped.\x1b[0m\n");
        return Ok(());
    }

    println!("\n\x1b[36m>> Installing / updating selected shell completions...\x1b[0m\n");
    let mut updated_count = 0;
    for idx in selected_indices {
        let item = &available_or_installed[idx];
        match install_completions(item.shell, cmd) {
            Ok(res) => {
                print!("{}", res.message);
                updated_count += 1;
            }
            Err(e) => {
                eprintln!(
                    "  \x1b[1;31m✗\x1b[0m Failed to update completions for {}: {e}",
                    item.shell
                );
            }
        }
    }

    println!(
        "\n\x1b[1;32m✓ Successfully configured completions for {} shell(s).\x1b[0m\n",
        updated_count
    );
    Ok(())
}

fn generate_bash_completions(cmd: &mut clap::Command) -> String {
    let mut buf = Vec::new();
    generate(shells::Bash, cmd, "forgum", &mut buf);
    let mut script = String::from_utf8_lossy(&buf).into_owned();

    // Enrich with discrete value completion lists for bash
    let enrichment = r#"
# Forgum dynamic value completion helpers for bash
_forgum_effects="moonwalk walk breathe float fly talk sway pulse glitch particles dissolve animal_natural natural"
_forgum_mountains="hills peaks volcano iceberg skyline seamount plateau crater gothic castle garden none"
_forgum_roads="dirt cobblestone magma ice seabed sidewalk roof grid crypt savanna mud tracks checkerboard none"
_forgum_environments="pasture inferno ocean arctic city forest savanna swamp space cyber graveyard jurassic hive throne none"
_forgum_colors="natural animal_natural default animal rainbow lolcat solid none"
_forgum_animals="apt armadillo atat bearface beavis.zen bees bill-the-cat bud-frogs bunny cat cat2 catfence charizardvice charlie claw-arm corgi cower cowfee cthulhu-mini daemon default docker-whale doge dolphin dragon dragon-and-cow duck ebi_furai elephant elephant-in-snake elephant2 eyes fat-banana fat-cow fence flaming-sheep fox ghost ghostbusters glados goat goat2 golden-eagle hamster happy-whale hedgehog hellokitty hippie hiya hypno jellyfish jesus king kiss kitten kitty knight koala kosh lamb lamb2 lobster lollerskates luke-koala mech-and-cow meow minotaur mona-lisa moofasa mooghidjirah moojira moose mule mutilated nyan octopus owl panther pawn periodic-table personality-sphere pig pterodactyl pufferfish queen radioactive-kitty ram ren rhino rook rooster satanic sauron seahorse seahorse-big sheep shikato shrug skeleton sloth small smiling-octopus snoopy snoopyhouse snoopysleep spidercow squid squirrel stegosaurus stimpy supermilker surgery telebears three-eyes tiger tortoise turkey turtle tux tux-big tweety-bird unipony vader viper vulpix walrus weeping-angel whale wizard wolf world yoda random"
_forgum_accel="auto dedicated integrated npu cpu"
_forgum_attach_modes="startup prompt clear split pane"
_forgum_aspects="auto 21:9 16:9 16:10 4:3 1:1 narrow"
_forgum_aspect_modes="preset dynamic auto"
_forgum_render_modes="ascii braille halfblock hybrid"
_forgum_contrast_modes="standard acrylic_glass high_contrast vibrant"
_forgum_colorblind="none protanopia deuteranopia tritanopia achromatopsia protanopia_sim deuteranopia_sim tritanopia_sim"
_forgum_time_of_day="auto dawn day dusk night"
_forgum_seasons="auto spring summer autumn winter"

_forgum_custom_complete() {
    local cur="${COMP_WORDS[COMP_CWORD]}"
    local line="$COMP_LINE"
    local lsp_out=$(forgum complete-context --bash --line "$line" --word "$cur" 2>/dev/null)
    if [[ -n "$lsp_out" ]]; then
        COMPREPLY=( $(compgen -W "$lsp_out" -- "$cur") )
        return 0
    fi
    local prev="${COMP_WORDS[COMP_CWORD-1]}"
    case "$prev" in
        --effect|-e)
            COMPREPLY=( $(compgen -W "$_forgum_effects" -- "$cur") )
            return 0
            ;;
        --mountain)
            COMPREPLY=( $(compgen -W "$_forgum_mountains" -- "$cur") )
            return 0
            ;;
        --road)
            COMPREPLY=( $(compgen -W "$_forgum_roads" -- "$cur") )
            return 0
            ;;
        --environment)
            COMPREPLY=( $(compgen -W "$_forgum_environments" -- "$cur") )
            return 0
            ;;
        --time-of-day|--tod)
            COMPREPLY=( $(compgen -W "$_forgum_time_of_day" -- "$cur") )
            return 0
            ;;
        --season)
            COMPREPLY=( $(compgen -W "$_forgum_seasons" -- "$cur") )
            return 0
            ;;
        --color-mode)
            COMPREPLY=( $(compgen -W "$_forgum_colors" -- "$cur") )
            return 0
            ;;
        --colorblind|--cvd)
            COMPREPLY=( $(compgen -W "$_forgum_colorblind" -- "$cur") )
            return 0
            ;;
        --cow|--animal|-a)
            COMPREPLY=( $(compgen -W "$_forgum_animals" -- "$cur") )
            return 0
            ;;
        --accel)
            COMPREPLY=( $(compgen -W "$_forgum_accel" -- "$cur") )
            return 0
            ;;
        --shell-attach-mode|--attach-mode)
            COMPREPLY=( $(compgen -W "$_forgum_attach_modes" -- "$cur") )
            return 0
            ;;
        --aspect|--aspect-ratio)
            COMPREPLY=( $(compgen -W "$_forgum_aspects" -- "$cur") )
            return 0
            ;;
        --aspect-mode)
            COMPREPLY=( $(compgen -W "$_forgum_aspect_modes" -- "$cur") )
            return 0
            ;;
        --render-mode)
            COMPREPLY=( $(compgen -W "$_forgum_render_modes" -- "$cur") )
            return 0
            ;;
        --contrast-mode|--contrast)
            COMPREPLY=( $(compgen -W "$_forgum_contrast_modes" -- "$cur") )
            return 0
            ;;
    esac
    return 1
}
"#;
    script.push_str(enrichment);
    script
}

