fn generate_xonsh_completions() -> String {
    r#"# Xonsh completion specification for Forgum
from xonsh.completers.tools import *

@contextual_command_completer_for("forgum")
def _forgum_completer(command):
    opts = {
        "--animal", "--cow", "-a", "--effect", "-e", "--mountain", "--road",
        "--environment", "--color-mode", "--colorblind", "--cvd", "--text", "--duration", "-d",
        "--fps", "--thought-interval", "--eyes", "--tongue", "--palette",
        "--think", "--background", "-b", "--banner", "-B", "--split-scroll",
        "--reserve-rows", "--reserve-cols", "--split-ratio",
        "--accel", "--shell-attach-mode", "--aspect", "--aspect-mode",
        "render", "think", "fortune", "options", "list", "completions",
        "init", "tui", "status", "doctor", "checkhealth", "config", "logs",
        "herd", "theme", "demo", "showcase", "say", "help",
        "moo", "vibe", "touch-grass", "chad", "zoomies", "yeet", "moonwalk"
    }
    return opts
"#
    .to_string()
}

