fn generate_yash_completions() -> String {
    r#"# Yash completion for Forgum
function completion/forgum {
    typeset -a commands
    commands=(render think fortune list completions init tui status doctor checkhealth config logs herd theme demo showcase say install uninstall update help moo vibe touch-grass chad zoomies yeet moonwalk)
    complete -c commands
}
"#
    .to_string()
}

// ═══════════════════════════════════════════════════════════════════════════
// LSP Context-Aware Autocompletion Engine & Unified Metadata Registry
// ═══════════════════════════════════════════════════════════════════════════

/// Completion candidate kind (Command, ParameterName, ParameterValue, Positional).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompletionKind {
    Command,
    ParameterName,
    ParameterValue,
    Positional,
}

impl CompletionKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            CompletionKind::Command => "Command",
            CompletionKind::ParameterName => "ParameterName",
            CompletionKind::ParameterValue => "ParameterValue",
            CompletionKind::Positional => "ParameterValue",
        }
    }
}

/// Completion candidate returned by LSP context resolution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CompletionCandidate {
    pub name: &'static str,
    pub display: &'static str,
    pub kind: CompletionKind,
    pub description: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SubcommandMeta {
    pub name: &'static str,
    pub aliases: &'static [&'static str],
    pub description: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FlagMeta {
    pub long: &'static str,
    pub short: Option<&'static str>,
    pub aliases: &'static [&'static str],
    pub description: &'static str,
    pub takes_value: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ChoiceMeta {
    pub value: &'static str,
    pub description: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ConfigKeyMeta {
    pub key: &'static str,
    pub aliases: &'static [&'static str],
    pub value_type: &'static str,
    pub description: &'static str,
}

